package com.bank.fee;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.*;

public class KissYagniDemo {
    private static final Logger log = Logger.getLogger(KissYagniDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FeeCalculator calc = new FeeCalculator();

        log.info("=== KISS/YAGNI: simplest fee that meets today's need ===");
        TransferRequest small = new TransferRequest("SAV2001", "CUR3001", new BigDecimal("40000"));
        log.info(() -> "Fee for Rs." + small.getAmount() + " = Rs." + calc.computeFee(small));

        // A REAL second requirement arrived: large transfers use a percentage fee.
        // Extending the simple design is a tiny, clear change — no speculative machinery needed.
        log.info("=== Real second rule appears — extend simply ===");
        TransferRequest large = new TransferRequest("SAV2001", "CUR3001", new BigDecimal("1200000"));
        log.info(() -> "Fee for Rs." + large.getAmount() + " = Rs." + calc.computeFee(large));
    }
}

