class TransferRequest {
    private final String fromId;
    private final String toId;
    private final BigDecimal amount;
    TransferRequest(String fromId, String toId, BigDecimal amount) {
            this.fromId = fromId;
            this.toId = toId
            this.amount = amount;
    }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in service/FeeCalculator.java ───
// KISS: a plain method. YAGNI: NO rules engine, NO plugin framework, NO message broker.
//
// What we deliberately did NOT build (YAGNI violations we avoided):
//   - a FeeStrategy interface + registry + dynamic loading for ONE rule
//   - a Kafka topic to "publish fee events" nobody consumes yet
//   - a generic configurable rules engine for three fixed numbers
class FeeCalculator {
    private static final BigDecimal FLAT_FEE = new BigDecimal("25.00");
    private static final BigDecimal LARGE_THRESHOLD = new BigDecimal("1000000");
    private static final BigDecimal LARGE_RATE = new BigDecimal("0.0005"); // 0.05%

    BigDecimal computeFee(TransferRequest req) {
        BigDecimal amount = req.getAmount();
        // Today's two REAL rules — expressed as the simplest correct code.
        if (amount.compareTo(LARGE_THRESHOLD) > 0) {
            return amount.multiply(LARGE_RATE).setScale(2, RoundingMode.HALF_UP);
        }
        return FLAT_FEE;
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
